  "Every view, download, and print of an original Jotform PDF is recorded here with user, timestamp, IP, and success status. This log is append-only and survives submission deletion via text snapshots.": { es: "Cada vista, descarga e impresi\u00f3n de un PDF original de Jotform queda registrada aqu\u00ed con la persona, la fecha y hora, la IP y el resultado. Este registro solo crece y se conserva aunque el env\u00edo se elimine, gracias a copias en texto." },
  "Every view, download, print and email of a form's PDF, from Jotform or from the app, is recorded here with the person, the time, the address it came from and whether it succeeded. This log is append-only and survives a submission's deletion through text snapshots.": { es: "Cada vista, descarga, impresi\u00f3n y correo del PDF de un formulario, de Jotform o de la app, queda registrado aqu\u00ed con la persona, la hora, la direcci\u00f3n desde la que se hizo y si tuvo \u00e9xito. Este registro solo agrega y sobrevive a la eliminaci\u00f3n de un env\u00edo mediante copias de texto." },
