  "Pull the latest forms from Jotform. Only forms whose title starts with {0} are imported. Forms in the app that no longer match are switched off and kept, with their submissions. Continue?": { es: "Descargar los formularios m\u00e1s recientes de Jotform. Solo se importan los formularios cuyo t\u00edtulo empieza con {0}. Los formularios de la aplicaci\u00f3n que ya no coinciden se apagan y se conservan, con sus env\u00edos. \u00bfContinuar?" },
  "Pulls every submission from Jotform for every enabled form, ignoring the incremental filter. Existing cached submissions are re-fetched and their metadata is refreshed (submitter name, email, matched employee, expiry). Admin-set fields (status, notes, manual expiry, entity links) are preserved.": { es: "Trae cada env\u00edo de Jotform de cada formulario habilitado, sin el filtro incremental. Los env\u00edos ya guardados se vuelven a obtener y se actualizan sus metadatos (nombre del remitente, correo, persona asociada, vencimiento). Los campos fijados por un administrador (estado, notas, vencimiento manual, v\u00ednculos a registros) se conservan." },
