  "Re-run Auto-Link": { es: "Volver a vincular autom\u00e1ticamente" },
  "Re-run Auto-Link?\n\nThis scans every unlinked submission and matches it against the users table by employee ID, email, or exact full name. Ambiguous matches (multiple users) are left unlinked for manual review. Submitters that don't exist in the users table will also remain unlinked.\n\nThis action is safe to run any number of times.": { es: "\u00bfVolver a ejecutar la vinculaci\u00f3n autom\u00e1tica?\n\nRevisa cada env\u00edo sin vincular y lo compara con la tabla de usuarios por n\u00famero de empleado, correo o nombre completo exacto. Las coincidencias ambiguas (varios usuarios) se dejan sin vincular para revisarlas a mano. Quienes no existen en la tabla de usuarios tambi\u00e9n quedan sin vincular.\n\nEsta acci\u00f3n se puede ejecutar las veces que haga falta." },
