  "Temporary PIN": { es: "PIN temporal" },
  "Text size": { es: "Tama\u00f1o del texto" },
  "That employee ID is already in use.": { es: "Ese n\u00famero de identificaci\u00f3n de empleado ya est\u00e1 en uso." },
  "That one is for admins. Ask an admin to take a look.": { es: "Ese es para administradores. P\u00eddale a un administrador que lo revise." },
  "The Jotform Count is what Jotform's API reports for each form. The Our Count is what we have stored. A positive Delta means Jotform has submissions we never picked up. Click \"Show Missing IDs\" to see which specific submissions are missing and Force Fetch them one at a time. Unresolved Failures are submissions the sync attempted to insert but errored on. Use the Failures table below to retry or dismiss them.": { es: "El conteo de Jotform es lo que informa la API de Jotform para cada formulario. El conteo nuestro es lo que tenemos guardado. Una diferencia positiva significa que Jotform tiene env\u00edos que nunca recogimos. Presione \"Mostrar los ID faltantes\" para ver cu\u00e1les faltan y forzar su descarga uno por uno. Los fallos sin resolver son env\u00edos que la sincronizaci\u00f3n intent\u00f3 insertar y dieron error. Use la tabla de fallos de abajo para reintentarlos o descartarlos." },
  "The case goes back to the team.": { es: "El caso vuelve al equipo." },
  "The connection dropped. Your answer is saved.": { es: "Se perdi\u00f3 la conexi\u00f3n. La respuesta qued\u00f3 guardada." },
  "The forms connection is not set up. Ask your administrator.": { es: "La conexi\u00f3n de formularios no est\u00e1 configurada. P\u00eddale ayuda a su administrador." },
  "The person reads your note in the app. Their notice shows only the dates.": { es: "La persona lee su nota en la aplicaci\u00f3n. Su aviso muestra solo las fechas." },
  "The schedule fills 8 weeks ahead and keeps extending until the pattern is ended.": { es: "El horario se llena con 8 semanas de anticipaci\u00f3n y sigue extendi\u00e9ndose hasta que el patr\u00f3n termine." },
  "The scheduled shift will be cancelled and posted as an open shift for eligible staff to claim.": { es: "El turno programado se cancela y se publica como turno abierto para que el personal elegible lo tome." },
  "The source record could not be found. It may have been deleted or the entry was logged with a temporary reference.": { es: "No se encontr\u00f3 el registro de origen. Es posible que se haya eliminado o que la entrada se registrara con una referencia temporal." },
  "The task will appear in the staff member's \"Assigned Tasks\" tab where they can mark it as in progress, resolved, or unable to resolve.": { es: "La tarea aparecer\u00e1 en la pesta\u00f1a \"Tareas asignadas\" de la persona, donde podr\u00e1 marcarla como en curso, resuelta o imposible de resolver." },
  "The team promised a response within 72 hours of filing.": { es: "El equipo se comprometi\u00f3 a responder en un plazo de 72 horas desde la presentaci\u00f3n." },
  "Then add it to your home screen from that browser.": { es: "Luego agr\u00e9guela a su pantalla de inicio desde ese navegador." },
  "These decide what buzzes your phone in the staff app. The bell here keeps everything.": { es: "Esto decide lo que suena en su tel\u00e9fono en la aplicaci\u00f3n del personal. La campana aqu\u00ed guarda todo." },
  "These people are told about this form as well as anyone under Every form.": { es: "Estas personas reciben avisos de este formulario, igual que quienes est\u00e1n en Todos los formularios." },
  "These still need an answer": { es: "Estas todav\u00eda necesitan respuesta" },
  "They will get an email. The email carries no case text.": { es: "Recibir\u00e1 un correo. El correo no incluye el texto del caso." },
  "This did not load.": { es: "Esto no se carg\u00f3." },
  "This form could not be read. Close the window and try again.": { es: "No se pudo leer este formulario. Cierre la ventana e intente de nuevo." },
  "This form was already sent.": { es: "Este formulario ya se envi\u00f3." },
  "This Month": { es: "Este mes" },
  "This question cannot be answered here yet. Your supervisor will finish it.": { es: "Esta pregunta todav\u00eda no se puede responder aqu\u00ed. Su supervisor la completar\u00e1." },
  "This question is full.": { es: "Esta pregunta est\u00e1 llena." },
  "This Week": { es: "Esta semana" },
  "This affects future auto-matching. Existing linked submissions are not changed.": { es: "Esto afecta las futuras vinculaciones autom\u00e1ticas. Los env\u00edos ya vinculados no cambian." },
  "This case is not available.": { es: "Este caso no est\u00e1 disponible." },
  "This issue is currently assigned to someone. Selecting a new person will remove the previous assignment.": { es: "Esta incidencia ya est\u00e1 asignada a alguien. Elegir a otra persona quita la asignaci\u00f3n anterior." },
  "This item was not scored (inspection not yet completed).": { es: "Este elemento no se calific\u00f3 (la inspecci\u00f3n a\u00fan no se completa)." },
  "This page is for admins.": { es: "Esta p\u00e1gina es para administradores." },
  "This photo could not be read here. Choose a JPEG or PNG, or take a screenshot of it.": { es: "No se pudo leer esta foto aqu\u00ed. Elija un JPEG o un PNG, o t\u00f3mele una captura de pantalla." },
  "This report could not be found, or your account cannot open it.": { es: "No se encontr\u00f3 este informe, o su cuenta no puede abrirlo." },
  "This report's data source arrives with the report templates workstream. It will run here once that ships.": { es: "La fuente de datos de este informe llegar\u00e1 con las plantillas de informes. Se ejecutar\u00e1 aqu\u00ed cuando est\u00e9 disponible." },
  "This shift is open in the marketplace and available for staff to claim.": { es: "Este turno est\u00e1 abierto en el tablero y cualquier persona elegible puede tomarlo." },
  "This shift runs past midnight. Pick the day it starts.": { es: "Este turno pasa de la medianoche. Elija el d\u00eda en que comienza." },
  "This source arrives with the report templates workstream. You can save the report now, and it will run once its data source ships.": { es: "Esta fuente llegar\u00e1 con las plantillas de informes. Puede guardar el informe ahora y se ejecutar\u00e1 cuando su fuente de datos est\u00e9 disponible." },
