  "Use this as a reference. Change what one person may do under By person.": { es: "\u00daselo como referencia. Lo que una persona puede hacer se cambia en Por persona." },
  "Use this only when you have a specific reason, such as: you have made changes in Jotform that are not appearing here, the field-extraction logic has changed, or you suspect the cache is out of sync. For normal daily operations, the regular \"Sync All Submissions\" button is sufficient.": { es: "\u00dasela solo con un motivo concreto, por ejemplo: hizo cambios en Jotform que no aparecen aqu\u00ed, cambi\u00f3 la l\u00f3gica de extracci\u00f3n de campos, o sospecha que la copia local est\u00e1 desactualizada. Para el trabajo diario basta con el bot\u00f3n \"Sincronizar todos los env\u00edos\"." },
  "Used by Speak Up. People only, never outside addresses. Nothing uses this until the Speak Up update.": { es: "Lo usa Confianza. Solo personas, nunca direcciones externas. Nada lo usa hasta la actualizaci\u00f3n de Confianza." },
