  "When a submitter's name or email does not exactly match a user record, auto-link falls back to the alias table. Aliases are added in two ways: (a) automatically whenever an admin manually links a submission to a user (source = manual_link), and (b) explicitly in this tab (source = admin_added). The five-tier matching order is: employee ID exact, email exact, email alias, name exact, name alias. Each alias's last_matched_at and match_count show when and how often it has helped.": { es: "Cuando el nombre o el correo de un remitente no coincide exactamente con un registro de usuario, la vinculaci\u00f3n autom\u00e1tica recurre a la tabla de alias. Los alias se agregan de dos formas: (a) autom\u00e1ticamente cada vez que un administrador vincula a mano un env\u00edo con una persona (source = manual_link), y (b) de forma expl\u00edcita en esta pesta\u00f1a (source = admin_added). El orden de coincidencia, en cinco niveles, es: ID de empleado exacto, correo exacto, alias de correo, nombre exacto, alias de nombre. Los campos last_matched_at y match_count de cada alias muestran cu\u00e1ndo y cu\u00e1ntas veces ha servido." },
  "When set, each submission will auto-compute an expiry date.": { es: "Si se indica, cada env\u00edo calcular\u00e1 su fecha de vencimiento autom\u00e1ticamente." },
