  "Completed on {0}. Disclosure: {1}.": { es: "Hecha el {0}. Divulgaci\u00f3n: {1}." },
  "Record the review": { es: "Registrar la revisi\u00f3n" },
  "For a date entered wrongly. The clearance keeps its place, its expiry is worked out again from the right date, and the correction is recorded with your reason.": { es: "Para una fecha anotada por error. La autorizaci\u00f3n conserva su lugar, su vencimiento se calcula de nuevo con la fecha correcta y la correcci\u00f3n queda registrada con su motivo." },
  "The employment history review the school can ask to see.": { es: "La revisi\u00f3n del historial laboral que la escuela puede pedir ver." },
  "A clearance is renewed every 60 months from the date on it. The one there now stays in the history.": { es: "Una autorizaci\u00f3n se renueva cada 60 meses a partir de la fecha que tiene. La que hay ahora queda en el historial." },
