  "Print the plan": { es: "Imprimir el plan" },
  "The hours this building needs, task by task, and the staff that follows, from the quote used as its plan. It shows no price.": { es: "Las horas que necesita este edificio, tarea por tarea, y el personal que resulta, de la cotizaci\u00f3n usada como su plan. No muestra ning\u00fan precio." },
  "The quote changed after this plan took it. Use the quote again to update the plan.": { es: "La cotizaci\u00f3n cambi\u00f3 despu\u00e9s de que este plan la tom\u00f3. Vuelva a usar la cotizaci\u00f3n para actualizar el plan." },
  "From quote {0}, revision {1}, taken on {2} by {3}.": { es: "De la cotizaci\u00f3n {0}, revisi\u00f3n {1}, tomado el {2} por {3}." },
