  "Update the plan": { es: "Actualizar el plan" },
  "End the plan": { es: "Terminar el plan" },
  "End this site's workload plan? It moves to the earlier plans, and the site has no plan until a quote is used again.": { es: "\u00bfTerminar el plan de carga de trabajo de este sitio? Pasa a los planes anteriores, y el sitio no tiene plan hasta que se vuelva a usar una cotizaci\u00f3n." },
