  "The evidence pack for a monthly review or a quarterly management review under OCSA-QMS-018, for every site, in the order of the review's agenda. What the platform does not hold prints as lines to fill in at the review.": { es: "El paquete de evidencias para una revisi\u00f3n mensual o una revisi\u00f3n trimestral por la direcci\u00f3n seg\u00fan OCSA-QMS-018, para todos los sitios, en el orden de la agenda de la revisi\u00f3n. Lo que la plataforma no tiene se imprime como l\u00edneas para completar en la revisi\u00f3n." },
