  "The evidence pack is circulated at least five working days before a quarterly or annual review. Every agenda item is here in its order; what the platform does not hold is left to fill in at the review.": { es: "El paquete de evidencias se distribuye al menos cinco d\u00edas h\u00e1biles antes de una revisi\u00f3n trimestral o anual. Cada punto de la agenda est\u00e1 aqu\u00ed en su orden; lo que la plataforma no tiene queda para completar en la revisi\u00f3n." },
